buggyCode:
BigDecimal shippingFee(BigDecimal subtotal) {
    if (subtotal.equals(BigDecimal.ZERO)) {
        return BigDecimal.ZERO;
    }
    return new BigDecimal("30000");
}

// subtotal đọc từ DB: JDBC trả BigDecimal mang scale của cột
BigDecimal fromDb = new BigDecimal("0.00");
System.out.println(shippingFee(BigDecimal.ZERO));
System.out.println(shippingFee(fromDb));

fix.code:
BigDecimal shippingFee(BigDecimal subtotal) {
    if (subtotal.signum() == 0) {          // hoặc compareTo(BigDecimal.ZERO) == 0
        return BigDecimal.ZERO;
    }
    return new BigDecimal("30000");
}
